import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Πληρωμές και συμφωνία συναλλαγών","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/payments-and-reconciliation.md","filePath":"el/plus/payments-and-reconciliation.md"}'),r={name:"el/plus/payments-and-reconciliation.md"};function o(n,a,s,c,h,d){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="πληρωμες-και-συμφωνια-συναλλαγων" tabindex="-1">Πληρωμές και συμφωνία συναλλαγών <a class="header-anchor" href="#πληρωμες-και-συμφωνια-συναλλαγων" aria-label="Permalink to &quot;Πληρωμές και συμφωνία συναλλαγών&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><p>Ελέγξτε το ιστορικό πληρωμών και επιστροφών και διακρίνετε την καταγραφή είσπραξης από την έναρξη συναλλαγής παρόχου.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Ανοίξτε Payments &amp; Billing και επιλέξτε τη σχετική κράτηση. Ελέγξτε το ιστορικό και το υπόλοιπο πριν από καταχώριση.</li><li>Για εξουσιοδοτημένη είσπραξη ελέγξτε Rail / Provider, Payment Kind (εξόφληση, προκαταβολή, μερική πληρωμή ή υπόλοιπο), Amount (EUR) και Receipt / Reference Note. Ποτέ αριθμούς καρτών. Καταγράψτε μόνο πραγματική τεκμηριωμένη είσπραξη.</li><li>Αν η συναλλαγή παρόχου είναι αβέβαιη, ελέγξτε Provider reconciliation και τις διαθέσιμες ενέργειες ανάκτησης ή επιθεώρησης αντί για νέα χρέωση. Οι επιστροφές απαιτούν κατάλληλο ρόλο και αιτιολογία.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Η επιλογή παρόχου δεν αποδεικνύει ενεργή ηλεκτρονική πληρωμή. Όχι πραγματικές χρεώσεις ή επιστροφές στην εκπαίδευση. Η αξία κράτησης δεν είναι είσπραξη· συμφωνήστε την αβέβαιη συναλλαγή πριν επαναλάβετε.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul><h2 id="εμπορικη-οικονομικη-λειτουργια-v0-7-26" tabindex="-1">Εμπορική οικονομική λειτουργία v0.7.26 <a class="header-anchor" href="#εμπορικη-οικονομικη-λειτουργια-v0-7-26" aria-label="Permalink to &quot;Εμπορική οικονομική λειτουργία v0.7.26&quot;">​</a></h2><p>Η μερική είσπραξη και η φυσική παράδοση έχουν χωριστές εγγραφές. Ελέγξτε απόδειξη, αρχικό οδηγό και πραγματικά μετρητά πριν επιβεβαιώσετε φύλαξη· δείτε <a href="/el/plus/cash-management.html">Μετρητά</a>. Ελέγξτε χωριστά προμηθευτές μέσω <a href="/el/plus/subcontractors.html">Υπεργολάβων</a>. Ο δείκτης Collected / Authorized περιλαμβάνει εγκρίσεις, ενώ το Outstanding δεν είναι ακριβές υπόλοιπο μετά από μερική πληρωμή· συμφωνήστε με επιμέρους εγγραφές. Η ενεργοποίηση εξωτερικού PSP διαφέρει από καταγραφή είσπραξης. Δείτε <a href="/el/integrations/payment-api-setup.html">Ρύθμιση πληρωμών</a>.</p>',13)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
